
const D={"type": "עור שמן", "profile": "עור המתאפיין בהפרשה מוגברת של סבום, בעיקר באזור ה-T (מצח, אף, סנטר). ברק שומני, נקבוביות פעורות ונטייה לפצעונים ולשחורים.", "needs": "לא לייבש — לאזן. לחות קלה, מרכיבים מאזנים ואנטי-בקטריאליים עדינים, וניקוי מותאם שלא פוגע במחסום העורי.", "routine": {"בוקר": "שוטפים פנים במים או סבון עדין, מי פנים, וקרם יום קליל. אפשר להוסיף סרום ג'ל קל לפי הצורך.", "ערב": "מתאפרת? מתחילים במסיר איפור שומני. ממשיכים בשמן הידרופילי, מי פנים לאיזון, ולסיום סרום קליל או קרם לילה מתאים.", "פעם-פעמיים בשבוע": "פילינג גרגרים עדין ואחריו מסיכת חימר ירוק. אין לנקות יותר מפעמיים ביום — ניקוי יתר מגרה את בלוטות החלב."}, "products": [["מסיר איפור שומני", "על בסיס שמנים צמחיים — ממיס איפור, לכלוך ושומן בעדינות בלי לייבש."], ["שמן הידרופילי", "תכשיר ניקוי שומני שנשטף במים, מנקה לעומק בלי תחושת שומניות."], ["פילינג גרגרים", "פילינג עדין להסרת תאי עור מתים, שומר על נקבוביות נקיות ומחליק את המרקם."], ["מסיכת חימר", "חימר ירוק שסופח שומן עודף, מכווץ נקבוביות ומעניק מראה מט ואחיד."], ["מי פנים", "מאזנים את ה-pH, מרגיעים גירוי ומכווצים נקבוביות לאחר שטיפה."], ["קרם יום", "קרם קליל ולא-קומדוגני שמעניק לחות מבוקרת ומאזן את רמות השומן."]], "shop": [["שמן זרעי ענבים", "שמן נשא קליל ולא-קומדוגני, נספג מהר ומתאים במיוחד לעור שמן ומעורב."], ["שמן שקדים מתוקים", "שמן נשא עדין ורב-שימושי לכל סוגי העור. מרכך, מזין ובסיס מצוין למסירי איפור, שמני ניקוי וסרומים."], ["שמן גזר", "עשיר בבטא-קרוטן ונוגדי חמצון. מחיה ומחדש עור עייף ותומך במראה זוהר ואחיד."], ["ויטמין E", "נוגד חמצון מסיס בשמן — מגן על הפורמולה מהתחמצנות ומזין את העור."], ["פוליסורבט 80", "מתחלב עדין שמאפשר לשמן להישטף במים. הבסיס לשמן הידרופילי שנשטף נקי."], ["ג'ל בסיס", "בסיס ג'ל מימי קליל שמעניק מרקם קל ותחושת רעננות — אידיאלי לעור שמן ומעורב."], ["קרם בסיס", "בסיס מוכן (מים+שמן+מתחלב) שמשביחים לפי הצורך — חוסך הכנת קרם מאפס."], ["אקסטרקט אלוורה", "אלוורה מרגיעה, מלחלחת ומשקמת — מרככת גירוי ותומכת באיזון העור."], ["חימר ירוק", "חימר ספיגה חזק שסופח שומן עודף ומנקה לעומק — מתאים לעור שמן."], ["הידרוסול לבנדר", "מי פרחים מאזנים ומרגיעים, אנטיספטיים בעדינות — בסיס מצוין לעור שמן ומעורב."], ["אקסטרקט הממליס", "מכווץ נקבוביות ומאזן שומן, טוניק טבעי לעור שמן."], ["אבץ", "מינרל מאזן שמסייע בהפחתת שומניות ובהרגעת פצעונים."], ["אלנטואין", "מרגיע ומשקם, מזרז ריפוי ומרכך את העור."], ["תמצית אתרי לבנדר", "מרגיע, מאזן ואנטיספטי — מתאים לעור שמן ומעורב ולהרגעת פצעונים."], ["תמצית אתרי תפוז", "מרענן, ממריץ ומחיה עור עייף, עם ניחוח נעים ומרומם."], ["תמצית אתרי עשב לימון", "מרענן ומכווץ, בעל ניחוח מלבב ותכונות מאזנות לעור שמן."], ["אקסטרקט לימון", "מבהיר ומרענן, עשיר בנוגדי חמצון ותומך במראה אחיד."], ["אקסטרקט רימונים", "עשיר בנוגדי חמצון (פוליפנולים), תומך בחידוש ובמראה קורן."], ["גלעיני משמש טחונים", "גרגרי פילינג עדינים וקטנים לניקוי מכני של תאי עור מתים בלי לשרוט."], ["שמן נר הלילה", "עשיר בחומצת גמא-לינולנית (GLA) — מאזן, מרגיע ותומך בעור מעורב ובוגר."], ["שמן זרעי מלפפונים", "שמן קליל ומאזן, עשיר בנוגדי חמצון — מרענן ולא מכביד."], ["סקוולאן צמחי", "ליפיד קליל הדומה לשומן הטבעי של העור — נספג מהר ומעניק רכות בלי כובד."], ["גליצרין צמחי", "מושך לחות אל העור ושומר עליה — רכיב בסיס בתכשירי לחות."], ["אסקורביל פלמיטט", "נגזרת ויטמין C מסיסת שמן, נוגדת חמצון ותומכת בזוהר ובגוון אחיד."], ["תמצית אתרי גרניום", "מאזן, אנטיספטי ומחזיר זוהר. משתלב יפה בפורמולות פנים."]]};
